class AsyncActivationsResource:
    """One-time numbers: buy, wait for the code, finish, cancel."""

    def __init__(self, transport: AsyncTransport) -> None:
        self._t = transport

    async def create(self, *, service: str, country: str, webhook_url: Optional[str] = None, pool: Optional[Literal["auto", "pool1", "pool2", "pool3"]] = None, max_price: Optional[float] = None, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Purchase a Number — Deducts balance from your account and provisions a temporary phone number for the requested service. Once an OTP SMS arrives (within 20 minutes), it is delivered via: 1. **Webhook** — instantly POSTed to your configured global webhook URL, or the per-request `webhook_url` override. 2. **Polling** — call `GET /activations/{id}` at your preferred interval. 3. **Long-poll** — call `GET /activations/{id}/wait` to block until the OTP arrives or the window expires. If no OTP is received within 20 minutes, the charged amount is automatically refunded to your wallet."""
        return await self._t.request("POST", f"/activations", body=compact({"service": service, "country": country, "webhook_url": webhook_url, "pool": pool, "max_price": max_price}), idempotent=True, options=request_options)

    async def get(self, id: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Poll Activation Status — Returns the current status of an activation. Safe to call repeatedly at any interval. If the OTP has already been received, it is returned immediately from the database without an upstream call. If the activation is still `waiting`, a live upstream check is made and the result is cached in the database."""
        return await self._t.request("GET", f"/activations/{quote(id)}", options=request_options)

    async def wait_once(self, id: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Wait for OTP (Long-Poll) — Blocks the HTTP connection until an OTP is received or the activation expires (up to 20 minutes). Useful for simple integrations that want a single blocking call rather than a polling loop. For production workloads with multiple concurrent activations, the **Webhook** approach is strongly preferred."""
        return await self._t.request("GET", f"/activations/{quote(id)}/wait", options=request_options)

    async def finish(self, id: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Mark Code as Used — Closes a number that received its code (same as `PATCH /activations/{id}`). Not required — numbers close on their own when the window ends."""
        return await self._t.request("POST", f"/activations/{quote(id)}/finish", options=request_options)

    async def cancel(self, id: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Cancel and Refund — Releases a number that hasn't received an SMS yet and refunds it in full (same as `DELETE /activations/{id}`). Safe to retry — it refunds once."""
        return await self._t.request("POST", f"/activations/{quote(id)}/cancel", options=request_options)

    async def resend(self, id: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Request Another SMS — Asks for another SMS on a number that has already received one and is still open (for when the site asks you to request a new code). Free. The new SMS arrives as an `activation.sms_received` event and is appended to `sms`. Supported on Pool 1 numbers; others answer 409 `RESEND_NOT_SUPPORTED`."""
        return await self._t.request("POST", f"/activations/{quote(id)}/resend", options=request_options)

    async def list(self, *, status: Optional[Literal["waiting", "received", "finished", "expired", "canceled"]] = None, limit: Optional[int] = None, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """List My Numbers — Your one-time numbers, newest first. Open ones are synced with their pool first, so the list is current."""
        return await self._t.request("GET", f"/user/activations", query=compact({"status": status, "limit": limit}), options=request_options)


