    async def apple(self, *, signed_transaction: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Credit an App Store Purchase — For the iOS app. Send the StoreKit 2 `Transaction.jwsRepresentation` of a credit pack bought with `appAccountToken` set to `iap_account_token` from `GET /me`. It is verified against Apple's root certificate and credited once per transaction — safe to retry; finish the StoreKit transaction only after a 200. Test (sandbox) purchases are accepted only for allowlisted accounts. Errors: `INVALID_PURCHASE`, `UNKNOWN_PRODUCT`, `PURCHASE_REVOKED`, `ACCOUNT_MISMATCH`, `SANDBOX_NOT_ALLOWED`."""
