class AsyncAuthResource:
    """Sign-in and tokens."""

    def __init__(self, transport: AsyncTransport) -> None:
        self._t = transport

    async def token(self, *, grant_type: str, request_options: Optional[Dict[str, Any]] = None, **extra: Any) -> Dict[str, Any]:
        """Get Tokens — How apps, the browser extension, the CLI and MCP servers sign in. Returns a 15-minute access token and a 60-day refresh token that rotates on every use (re-using an old one signs that device out). Errors follow RFC 6749 (`{ error, error_description }`)."""
        return await self._t.request("POST", f"/oauth/token", body=compact({"grant_type": grant_type, **extra}), auth=False, options=request_options)

    async def send_email_code(self, *, email: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Email a Sign-In Code — Sends a 6-digit code (valid 10 minutes) to exchange with the `email_code` grant. Same answer whether or not the account exists."""
        return await self._t.request("POST", f"/oauth/email-code", body=compact({"email": email}), auth=False, options=request_options)

    async def start_device_sign_in(self, *, client: Optional[Literal["cli", "extension", "mcp", "other"]] = None, device_name: Optional[str] = None, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Start Device Sign-In — RFC 8628 device flow for the CLI, extension and MCP servers. Show `user_code`, open `verification_uri_complete` in a browser, then poll `/oauth/token` every `interval` seconds with `grant_type=urn:ietf:params:oauth:grant-type:device_code`."""
        return await self._t.request("POST", f"/oauth/device/code", body=compact({"client": client, "device_name": device_name}), auth=False, options=request_options)

    async def get_device_sign_in(self, *, user_code: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Look Up a Device Code — For the approval screen (numberotp.com/device, or the mobile app). Signed-in people only."""
        return await self._t.request("GET", f"/oauth/device", query=compact({"user_code": user_code}), options=request_options)

    async def decide_device_sign_in(self, *, user_code: str, action: Literal["approve", "deny"], request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Approve or Deny a Device"""
        return await self._t.request("POST", f"/oauth/device", body=compact({"user_code": user_code, "action": action}), options=request_options)

    async def revoke(self, *, token: str, request_options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Sign Out (Revoke a Refresh Token)"""
        return await self._t.request("POST", f"/oauth/revoke", body=compact({"token": token}), auth=False, options=request_options)


